import System.Exception;import System.ArgumentException;import System.Globalization.NumberFormatInfo;import java.nio.file.*;import java.util.*;
class NumberFormatInfoGroupSizesProbe {
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static String csv(int[] a){if(a==null)return "~";StringJoiner j=new StringJoiner(",");for(int v:a)j.add(Integer.toString(v));return j.toString();}
 static int[] sizes(String s){if(s.equals("~"))return null;if(s.isEmpty())return new int[0];String[] p=s.split(",");int[] a=new int[p.length];for(int i=0;i<a.length;i++)a[i]=Integer.parseInt(p[i]);return a;}
 static int[] seed(int n){return switch(n){case 0->new int[]{3};case 1->new int[]{1,2,0};case 2->new int[0];default->throw new AssertionError();};}
 static void set(NumberFormatInfo n,String p,int[] a){switch(p){case "NumberGroupSizes"->n.set_NumberGroupSizes(a);case "CurrencyGroupSizes"->n.set_CurrencyGroupSizes(a);case "PercentGroupSizes"->n.set_PercentGroupSizes(a);default->throw new AssertionError(p);}}
 static int[] get(NumberFormatInfo n,String p){return switch(p){case "NumberGroupSizes"->n.get_NumberGroupSizes();case "CurrencyGroupSizes"->n.get_CurrencyGroupSizes();case "PercentGroupSizes"->n.get_PercentGroupSizes();default->throw new AssertionError(p);};}
 static String snapshot(NumberFormatInfo n){return csv(n.get_NumberGroupSizes())+"|"+csv(n.get_CurrencyGroupSizes())+"|"+csv(n.get_PercentGroupSizes());}
 static String outcome(NumberFormatInfo n,String p,int[] a){try{set(n,p,a);return "OK";}catch(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null));}}
 static void check(String a,String e,String c){if(!a.equals(e))throw new AssertionError(c+" actual="+a+" expected="+e);}
 public static void main(String[] args)throws java.lang.Exception{int cases=0,groups=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);NumberFormatInfo n=new NumberFormatInfo();set(n,p[0],seed(Integer.parseInt(p[1])));int[] input=sizes(p[3]);check(snapshot(n),p[5],"before "+line);check(outcome(n,p[0],input),p[4],"result "+line);check(csv(input),p[7],"input preservation "+line);check(snapshot(n),p[6],"after set "+line);if(input!=null&&input.length>0)input[0]=8;check(snapshot(n),p[8],"input mutation "+line);int[] first=get(n,p[0]),second=get(n,p[0]);check(first!=second?"1":"0",p[9],"getter identities "+line);if(first.length>0)first[0]=7;check(snapshot(n),p[10],"getter mutation "+line);groups+=7;cases++;}java.lang.System.out.println("PASS NumberFormatInfo group sizes cases="+cases+" groups="+groups);}
}
